/* Shadery z gry Patient Zero (michalstankiewicz4-cell/PatientZero, js/render/*.js) — skopiowane bez zmian; tu tylko stałe teksty GLSL. */
export const NOISE = "\r\n    float hash12(vec2 p){ vec3 p3 = fract(vec3(p.xyx) * .1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\r\n    float vnoise(vec2 p){\r\n      vec2 i = floor(p), f = fract(p); vec2 u = f*f*(3.-2.*f);\r\n      return mix(mix(hash12(i), hash12(i+vec2(1.,0.)), u.x), mix(hash12(i+vec2(0.,1.)), hash12(i+vec2(1.,1.)), u.x), u.y);\r\n    }\r\n    float fbm(vec2 p){\r\n      float a = .5, s = 0.;\r\n      for (int i = 0; i < 5; i++){ s += a * vnoise(p); p = mat2(1.6, 1.2, -1.2, 1.6) * p; a *= .5; }\r\n      return s;\r\n    }\r\n    float fbm3(vec2 p){\r\n      float a = .5, s = 0.;\r\n      for (int i = 0; i < 3; i++){ s += a * vnoise(p); p = mat2(1.6, 1.2, -1.2, 1.6) * p; a *= .5; }\r\n      return s;\r\n    }\r\n  ";
export const LIGHT = "\r\n    uniform vec3 uCam;\r\n    uniform vec3 uLight;\r\n    uniform float uLightPow;\r\n    uniform float uFever;\r\n\r\n    // Światło \"endoskopu\" przy kamerze + półsferyczne światło otoczenia.\r\n    // wrap diffuse + rozpraszanie podpowierzchniowe na terminatorze + dwa płaty odblasku (mokra tkanka)\r\n    vec3 shade(vec3 P, vec3 N, vec3 albedo, float rough, float wet, float sss, vec3 sssCol){\r\n      vec3 Ld = uLight - P; float dist = length(Ld); vec3 L = Ld / dist;\r\n      vec3 V = normalize(uCam - P); vec3 Hh = normalize(L + V);\r\n      float att = uLightPow / (1.0 + 0.0016 * dist * dist);\r\n      // stożek reflektora\r\n      vec3 spotDir = normalize(vec3(0.0, 0.18, -1.0));\r\n      float cone = smoothstep(0.55, 0.92, dot(-L, spotDir)) * 0.85 + 0.15;\r\n      att *= cone;\r\n      float ndl = dot(N, L);\r\n      float wrap = max(0., (ndl + 0.45) / 1.45);\r\n      float term = smoothstep(-0.5, 0.2, ndl) * (1. - smoothstep(0.05, 0.7, ndl));\r\n      vec3 diff = albedo * wrap + sssCol * term * sss;\r\n      float ndh = max(dot(N, Hh), 0.);\r\n      float fres = 0.04 + 0.96 * pow(1. - max(dot(N, V), 0.), 5.);\r\n      float e = 2.0 / max(rough * rough, 0.002);\r\n      float spec = pow(ndh, e) * (e + 8.) / 25.13 * (0.05 + fres * 0.6);\r\n      float wetSpec = pow(ndh, 900.) * wet * 9.0;\r\n      vec3 col = (diff + vec3(1.0, 0.92, 0.86) * (spec * 0.45 + wetSpec)) * att;\r\n      float hemi = N.z * 0.5 + 0.5;\r\n      col += albedo * mix(vec3(0.030, 0.006, 0.006), vec3(0.085, 0.032, 0.03), hemi);\r\n      col += sssCol * sss * 0.03;\r\n      col *= mix(vec3(1.0), vec3(1.12, 0.94, 0.84), uFever);\r\n      return col;\r\n    }\r\n\r\n    // krew pochłania niebieski i zielony szybciej niż czerwony\r\n    vec3 bloodFog(vec3 col, vec3 P){\r\n      float dist = length(uCam - P);\r\n      float below = max(0., 4.2 - P.z);\r\n      vec3 absorb = exp(-vec3(0.030, 0.060, 0.070) * (dist * 0.35 + below * 3.2));\r\n      vec3 inscatter = vec3(0.085, 0.010, 0.009) * (1. - exp(-dist * 0.022));\r\n      return col * absorb + inscatter;\r\n    }\r\n  ";
export const CAUSTIC = "\r\n    float caustic(vec2 uv, float t){\r\n      vec2 p = mod(uv * 6.28318, 6.28318) - 250.0;\r\n      vec2 i = p; float c = 1.0; float inten = .005;\r\n      for (int n = 0; n < 4; n++){\r\n        float tt = t * (1.0 - (3.5 / float(n + 1)));\r\n        i = p + vec2(cos(tt - i.x) + sin(tt + i.y), sin(tt - i.y) + cos(tt + i.x));\r\n        c += 1.0 / max(length(vec2(p.x / (sin(i.x + tt) / inten + 1e-4), p.y / (cos(i.y + tt) / inten + 1e-4))), 1e-3);\r\n      }\r\n      c /= 4.0; c = 1.17 - pow(max(c, 0.0), 1.4);\r\n      return pow(abs(c), 8.0);\r\n    }\r\n  ";
export const RBC_VERT = "\r\n    varying vec3 vN; varying vec3 vP; varying vec3 vLocal; varying vec3 vCol;\r\n    void main(){\r\n      mat4 m = modelMatrix * instanceMatrix;\r\n      vec4 wp = m * vec4(position, 1.0);\r\n      vP = wp.xyz; vN = normalize(mat3(m) * normal); vLocal = position;\r\n      #ifdef USE_INSTANCING_COLOR\r\n        vCol = instanceColor;\r\n      #else\r\n        vCol = vec3(1.0);\r\n      #endif\r\n      gl_Position = projectionMatrix * viewMatrix * wp;\r\n    }\r\n  ";
export const SPECK_VERT = "\r\n    uniform float uPx;\r\n    attribute float aSize;\r\n    varying float vA;\r\n    void main(){\r\n      vec4 mv = modelViewMatrix * vec4(position, 1.0);\r\n      gl_PointSize = aSize * uPx / -mv.z;\r\n      vA = clamp(1.0 - (-mv.z) / 60.0, 0.0, 1.0);\r\n      gl_Position = projectionMatrix * mv;\r\n    }\r\n  ";
export const SPECK_FRAG = "\r\n    varying float vA;\r\n    void main(){\r\n      vec2 c = gl_PointCoord - 0.5; float r = dot(c, c) * 4.0;\r\n      float a = exp(-r * 3.0) * vA;\r\n      gl_FragColor = vec4(vec3(1.0, 0.55, 0.42) * a * 0.3, 1.0);\r\n    }\r\n  ";
export const RBC_FRAG_BODY = "\r\n    uniform float uThick;\r\n    varying vec3 vN; varying vec3 vP; varying vec3 vLocal; varying vec3 vCol;\r\n    void main(){\r\n      vec3 N = normalize(vN);\r\n      if (!gl_FrontFacing) N = -N;\r\n      float rr = length(vLocal.xz) / 0.46;\r\n      // środek krwinki jest cieńszy — prześwituje jaśniej\r\n      float thin = 1.0 - smoothstep(0.0, 0.62, rr);\r\n      vec3 alb = mix(vec3(0.50, 0.035, 0.03), vec3(0.85, 0.16, 0.10), thin * 0.65) * vCol;\r\n      vec3 col = shade(vP, N, alb, 0.3, 0.45, 0.9, vec3(0.9, 0.12, 0.06));\r\n      vec3 L = normalize(uLight - vP);\r\n      float back = max(0.0, dot(-N, L));\r\n      col += vec3(0.9, 0.12, 0.05) * back * (0.15 + thin * 0.4) * uLightPow * 0.12;\r\n      col = bloodFog(col, vP);\r\n      gl_FragColor = vec4(col, 1.0);\r\n    }\r\n  ";
export const SURF_VERT = "\r\n    varying vec3 vN; varying vec3 vP; varying vec3 vLocal;\r\n    uniform float uWave; uniform float uTimeL;\r\n    void main(){\r\n      vec3 p = position;\r\n      #ifdef FLAGELLUM\r\n        // wić: fala biegnąca wzdłuż osi, amplituda rośnie ku końcowi\r\n        float s = -p.y;\r\n        p.x += sin(s * 7.0 - uTimeL * 18.0) * 0.12 * s;\r\n        p.z += cos(s * 6.0 - uTimeL * 15.0) * 0.06 * s;\r\n      #endif\r\n      #ifdef USE_INSTANCING\r\n        mat4 m = modelMatrix * instanceMatrix;\r\n      #else\r\n        mat4 m = modelMatrix;\r\n      #endif\r\n      vec4 wp = m * vec4(p, 1.0);\r\n      vP = wp.xyz; vN = normalize(mat3(m) * normal); vLocal = position;\r\n      gl_Position = projectionMatrix * viewMatrix * wp;\r\n    }\r\n  ";
export const SURF_FRAG_BODY = "\r\n    uniform vec3 uAlbedo; uniform vec3 uSssCol; uniform float uSss; uniform float uRough; uniform float uWet;\r\n    uniform vec3 uEmit; uniform float uRim; uniform vec3 uRimCol; uniform float uAlpha; uniform float uGrain;\r\n    uniform float uFlash; uniform float uSlow; uniform float uTimeL;\r\n    varying vec3 vN; varying vec3 vP; varying vec3 vLocal;\r\n    void main(){\r\n      vec3 N = normalize(vN); if (!gl_FrontFacing) N = -N;\r\n      vec3 alb = uAlbedo;\r\n      if (uGrain > 0.0) {\r\n        float g = fbm(vLocal.xy * 9.0 + vLocal.z * 5.0 + uTimeL * 0.3);\r\n        alb *= 0.7 + g * uGrain;\r\n      }\r\n      alb = mix(alb, vec3(0.55, 0.75, 0.95), uSlow * 0.55);\r\n      vec3 col = shade(vP, N, alb, uRough, uWet, uSss, uSssCol);\r\n      vec3 V = normalize(uCam - vP);\r\n      float fr = pow(1.0 - max(dot(N, V), 0.0), 2.5);\r\n      col += uRimCol * fr * uRim + uEmit;\r\n      col += vec3(1.0, 0.95, 0.9) * uFlash * 2.5;\r\n      col = bloodFog(col, vP);\r\n      gl_FragColor = vec4(col, uAlpha);\r\n    }\r\n  ";
export const TISSUE_COMMON = "\r\n    uniform sampler2D uSdf;\r\n    uniform vec2 uWorldMin;\r\n    uniform vec2 uWorldSize;\r\n    uniform float uTime;\r\n    uniform float uBeat;\r\n    uniform sampler2D uOrgan;\r\n    float sdfAt(vec2 p){ return texture2D(uSdf, (p - uWorldMin) / uWorldSize).r; }\r\n    vec4 organAt(vec2 p){ return texture2D(uOrgan, (p - uWorldMin) / uWorldSize); }\r\n    // ile tu jest narządu litego (wątroba, nerka, pęcherzyk, miedniczka) — tam tkanka nie opada w ciemność\r\n    float organMask(vec4 o){ return max(max(o.r, smoothstep(0.0, 0.45, o.g)), max(o.b, o.a)); }\r\n    float baseH(float d, float org){\r\n      // w narządzie ściany są stromsze (cienkie płytki hepatocytów sięgają powierzchni przekroju)\r\n      // w narządzie płytszy przekrój: lity miąższ z rowkami naczyń zamiast głębokich jam\r\n      float wall = smoothstep(-0.25, mix(1.5, 0.55, org), d);\r\n      float h = mix(mix(-5.0, -1.8, org), mix(3.0, 1.4, org), wall);\r\n      h = mix(h, -16.0, smoothstep(7.5, 11.0, d) * (1.0 - org));\r\n      return h;\r\n    }\r\n  ";
export const TISSUE_VERT_BODY = "\r\n    varying vec3 vPos;\r\n    varying float vSdf;\r\n    void main(){\r\n      vec3 p = position;\r\n      float d = sdfAt(p.xy);\r\n      float h = baseH(d, organMask(organAt(p.xy)));\r\n      // skurcz: ściany lekko \"puchną\" ku środkowi, dno unosi się\r\n      h += uBeat * 0.35 * (1.0 - smoothstep(-6.0, 0.0, d));\r\n      p.z = h;\r\n      vec4 wp = modelMatrix * vec4(p, 1.0);\r\n      vPos = wp.xyz; vSdf = d;\r\n      gl_Position = projectionMatrix * viewMatrix * wp;\r\n    }\r\n  ";
export const TISSUE_FRAG_BODY = "\r\n    varying vec3 vPos;\r\n    varying float vSdf;\r\n\r\n    float detailH(vec2 p, float d, float org){\r\n      float floorM = 1.0 - smoothstep(-1.2, 0.2, d);\r\n      float topM = smoothstep(1.3, 1.9, d) * (1.0 - smoothstep(6.8, 8.0, d));\r\n      // beleczki mięśniowe: grzbietowy szum, rozciągnięty i zawinięty\r\n      vec2 w = vec2(fbm3(p * 0.12), fbm3(p * 0.12 + 7.3)) * 3.0;\r\n      vec2 q = p * vec2(0.55, 0.32) + w;\r\n      float r = 1.0 - abs(vnoise(q) * 2.0 - 1.0); r = r * r * r;\r\n      float r2 = 1.0 - abs(vnoise(q * 2.3 + 3.1) * 2.0 - 1.0); r2 = r2 * r2;\r\n      float trab = r * 1.0 + r2 * 0.35;\r\n      // włókna przeciętego mięśnia\r\n      float fib = sin(p.x * 2.6 + p.y * 0.8 + fbm3(p * 0.5) * 7.0) * 0.5 + 0.5;\r\n      float wallM = max(0.0, 1.0 - floorM - topM);\r\n      return floorM * trab * 0.9 * (1.0 - org) + topM * (fib * 0.14 + vnoise(p * 2.3) * 0.12) + wallM * vnoise(p * 1.7) * 0.22;\r\n    }\r\n    float fullH(vec2 p){ float d = sdfAt(p); float org = organMask(organAt(p)); return baseH(d, org) + detailH(p, d, org); }\r\n    // odległość do krawędzi sześciokąta (zraziki wątroby)\r\n    float hexEdge(vec2 p){\r\n      vec2 r = vec2(1.0, 1.7320508), h = r * 0.5;\r\n      vec2 a = mod(p, r) - h, b = mod(p - h, r) - h;\r\n      vec2 g = dot(a, a) < dot(b, b) ? a : b;\r\n      vec2 q = abs(g);\r\n      return 0.5 - max(dot(q, normalize(vec2(1.0, 1.7320508))), q.x);\r\n    }\r\n    uniform vec2 uKidS;\r\n\r\n    void main(){\r\n      vec2 p = vPos.xy;\r\n      float d = vSdf;\r\n      float e = 0.09;\r\n      float hx = fullH(p + vec2(e, 0.)) - fullH(p - vec2(e, 0.));\r\n      float hy = fullH(p + vec2(0., e)) - fullH(p - vec2(0., e));\r\n      vec3 N = normalize(vec3(-hx / (2. * e), -hy / (2. * e), 1.0));\r\n\r\n      float floorM = 1.0 - smoothstep(-1.2, 0.3, d);\r\n      float topM = smoothstep(1.3, 1.9, d);\r\n      float outerM = smoothstep(7.0, 9.5, d);\r\n      float det = detailH(p, d, organMask(organAt(p)));\r\n\r\n      // barwy (liniowe)\r\n      vec3 cLumen = vec3(0.36, 0.045, 0.040);\r\n      vec3 cRidge = vec3(0.70, 0.20, 0.17);\r\n      vec3 cMyo   = vec3(0.30, 0.055, 0.05);\r\n      vec3 cEndo  = vec3(0.88, 0.66, 0.62);\r\n      vec3 cFat   = vec3(0.34, 0.19, 0.045);\r\n      vec3 cOut   = vec3(0.025, 0.006, 0.008);\r\n\r\n      float n1 = fbm(p * 0.35);\r\n      vec3 alb = mix(cLumen, cRidge, clamp(det * 0.9 + n1 * 0.25, 0., 1.) * floorM + (1. - floorM) * 0.35);\r\n      // przecięty mięsień: smugi włókien i plamy\r\n      vec3 myo = cMyo * (0.75 + 0.5 * n1) * (0.85 + 0.3 * sin(p.x * 2.6 + p.y * 0.8 + fbm3(p * 0.5) * 7.0));\r\n      alb = mix(alb, myo, topM);\r\n      // wsierdzie — jasna, cienka linia na krawędzi przekroju\r\n      float rim = smoothstep(1.0, 1.4, d) * (1.0 - smoothstep(1.5, 2.0, d));\r\n      alb = mix(alb, cEndo * 0.7, rim * 0.7);\r\n      // nasierdzie z tłuszczem\r\n      float fat = smoothstep(0.48, 0.62, fbm(p * 0.22 + 4.0)) * smoothstep(5.5, 7.0, d) * (1.0 - outerM);\r\n      alb = mix(alb, cFat, fat);\r\n      // narządy jamy brzusznej (maski z tekstury)\r\n      vec4 o = organAt(p);\r\n      float orgM = organMask(o);\r\n      outerM *= 1.0 - orgM;\r\n      alb = mix(alb, cOut, outerM);\r\n      float topO = orgM * smoothstep(0.15, 0.55, d);\r\n      if (orgM > 0.001) {\r\n        float liv = o.r, kid = smoothstep(0.0, 0.45, o.g), med = smoothstep(0.62, 0.95, o.g);\r\n        float nO = fbm(p * 0.45);\r\n        // wątroba: czerwonobrązowy miąższ z siateczką zrazików i połyskującą torebką\r\n        float hxl = hexEdge(p / 7.0 + vec2(0.3, 0.1));\r\n        float lob = 1.0 - smoothstep(0.0, 0.06, hxl);\r\n        vec3 cLiv = vec3(0.17, 0.055, 0.03) * (0.78 + 0.45 * nO);\r\n        cLiv = mix(cLiv, vec3(0.40, 0.22, 0.09), lob * 0.6);\r\n        cLiv *= 0.9 + 0.2 * vnoise(p * 2.4);\r\n        // nerka: ziarnista kora, prążkowane piramidy rdzenia, jaśniejsza torebka włóknista\r\n        vec2 ks = p - uKidS;\r\n        float ang = atan(ks.y, ks.x);\r\n        float stripe = 0.5 + 0.5 * sin(ang * 70.0 + fbm3(p * 0.6) * 4.0);\r\n        vec3 cCor = vec3(0.40, 0.085, 0.06) * (0.8 + 0.35 * vnoise(p * 3.2) + 0.2 * nO);\r\n        vec3 cMed = mix(vec3(0.22, 0.04, 0.04), vec3(0.34, 0.07, 0.06), stripe);\r\n        vec3 cKid = mix(cCor, cMed, med);\r\n        float capsK = kid * (1.0 - smoothstep(0.18, 0.42, o.g));\r\n        cKid = mix(cKid, vec3(0.62, 0.36, 0.30), capsK * 0.8);\r\n        vec3 cGall = vec3(0.16, 0.20, 0.035) * (0.85 + 0.3 * nO);\r\n        vec3 cPale = vec3(0.66, 0.52, 0.27) * (0.85 + 0.25 * vnoise(p * 1.8));\r\n        vec3 cOrg = cLiv;\r\n        cOrg = mix(cOrg, cKid, kid);\r\n        cOrg = mix(cOrg, cGall, o.b);\r\n        cOrg = mix(cOrg, cPale, o.a);\r\n        alb = mix(alb, cOrg, topO);\r\n        // boki płytek i ściany naczyń w narządzie: barwa miąższu, ciemniejsza\r\n        alb = mix(alb, cOrg * 0.8, orgM * (1.0 - topO) * smoothstep(-0.3, 0.3, d) * 0.9);\r\n        // dno kanałów w narządzie: ciemna krew na tle miąższu\r\n        alb = mix(alb, cOrg * 0.5 + vec3(0.06, 0.0, 0.0), orgM * (1.0 - smoothstep(-0.6, 0.1, d)) * 0.55);\r\n      }\r\n\r\n      float rough = mix(0.22, 0.6, topM);\r\n      float wet = mix(1.0, 0.0, topM) * (1.0 - outerM) * (1.0 - fat);\r\n      rough = mix(rough, 0.45, fat);\r\n      // torebka narządów lekko błyszczy\r\n      wet = mix(wet, 0.35, topO); rough = mix(rough, 0.32, topO);\r\n            vec3 col = shade(vPos, N, alb, rough, wet, 0.9 * (1.0 - outerM), vec3(0.9, 0.12, 0.08));\r\n\r\n      // kaustyki na wilgotnym dnie i ścianach\r\n      float lumenM = 1.0 - smoothstep(0.5, 1.6, d);\r\n      vec2 cuv = p * 0.06 + vec2(uTime * 0.012, -uTime * 0.02);\r\n      if (lumenM > 0.001) {\r\n        float ca = caustic(cuv, uTime * 0.55) + 0.6 * caustic(cuv * 1.7 + 0.3, uTime * 0.7);\r\n        ca = clamp(ca, 0.0, 3.0);\r\n        float lightNear = 1.0 / (1.0 + 0.004 * dot(uLight - vPos, uLight - vPos));\r\n        col += vec3(1.0, 0.55, 0.42) * ca * lumenM * 0.22 * uLightPow * lightNear;\r\n      }\r\n\r\n      // okluzja w zagłębieniach przy ścianach\r\n      float ao = 1.0 - 0.6 * floorM * (1.0 - smoothstep(0.0, 2.6, -d));\r\n      ao *= 0.75 + 0.25 * smoothstep(0.0, 0.8, det);\r\n      col *= mix(1.0, ao, 1.0 - topM);\r\n\r\n      col *= 1.0 + uBeat * 0.08;\r\n      col = bloodFog(col, vPos);\r\n      gl_FragColor = vec4(col, 1.0);\r\n    }\r\n  ";
export const QUAD_VERT = "varying vec2 vUv; void main(){ vUv = uv; gl_Position = vec4(position.xy, 0.0, 1.0); }";
export const BRIGHT = "\r\n    uniform sampler2D tIn; uniform float uThresh; varying vec2 vUv;\r\n    void main(){\r\n      vec3 c = texture2D(tIn, vUv).rgb;\r\n      float l = max(c.r, max(c.g, c.b));\r\n      float k = max(0.0, l - uThresh); k = k * k / (k + 0.6);\r\n      gl_FragColor = vec4(c * (k / max(l, 1e-4)), 1.0);\r\n    }";
export const BLUR = "\r\n    uniform sampler2D tIn; uniform vec2 uDir; varying vec2 vUv;\r\n    void main(){\r\n      vec3 s = texture2D(tIn, vUv).rgb * 0.2270270;\r\n      s += texture2D(tIn, vUv + uDir * 1.3846153).rgb * 0.3162162;\r\n      s += texture2D(tIn, vUv - uDir * 1.3846153).rgb * 0.3162162;\r\n      s += texture2D(tIn, vUv + uDir * 3.2307692).rgb * 0.0702702;\r\n      s += texture2D(tIn, vUv - uDir * 3.2307692).rgb * 0.0702702;\r\n      gl_FragColor = vec4(s, 1.0);\r\n    }";
export const COPY = "uniform sampler2D tIn; varying vec2 vUv; void main(){ gl_FragColor = vec4(texture2D(tIn, vUv).rgb, 1.0); }";
export const COMPOSITE = "\r\n    uniform sampler2D tScene; uniform sampler2D tDepth; uniform sampler2D tDof;\r\n    uniform sampler2D tB1; uniform sampler2D tB2; uniform sampler2D tB3;\r\n    uniform vec2 uRes; uniform float uTime; uniform float uNear; uniform float uFar; uniform float uFocus;\r\n    uniform float uFever; uniform float uHit; uniform float uFade; uniform float uSlow; uniform float uExposure; uniform float uClean;\r\n    varying vec2 vUv;\r\n    float hash(vec2 p){ return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\r\n    float linDepth(float d){ float z = d * 2.0 - 1.0; return 2.0 * uNear * uFar / (uFar + uNear - z * (uFar - uNear)); }\r\n    vec3 aces(vec3 x){ return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0); }\r\n    void main(){\r\n      vec2 uv = vUv;\r\n      // falowanie gorąca\r\n      if (uFever > 0.001){\r\n        float n = sin(uv.y * 38.0 + uTime * 3.1) * sin(uv.x * 27.0 - uTime * 2.3);\r\n        uv += vec2(n, n * 0.6) * 0.0028 * uFever;\r\n      }\r\n      vec2 dc = uv - 0.5; float r2 = dot(dc, dc);\r\n      float ab = (0.006 + uHit * 0.03) * r2 * 4.0 * (1.0 - uClean);\r\n      vec3 col;\r\n      col.r = texture2D(tScene, uv - dc * ab).r;\r\n      col.g = texture2D(tScene, uv).g;\r\n      col.b = texture2D(tScene, uv + dc * ab).b;\r\n      // głębia ostrości: ostro w płaszczyźnie bakterii\r\n      float ld = linDepth(texture2D(tDepth, uv).r);\r\n      float coc = smoothstep(0.07, 0.42, abs(ld - uFocus) / uFocus) * (1.0 - uClean);\r\n      col = mix(col, texture2D(tDof, uv).rgb, coc);\r\n      vec3 bloom = texture2D(tB1, uv).rgb * 0.5 + texture2D(tB2, uv).rgb * 0.8 + texture2D(tB3, uv).rgb * 1.1;\r\n      col += bloom * mix(0.4, 0.15, uClean);\r\n      col *= uExposure;\r\n      col = mix(col, col * vec3(1.15, 0.95, 0.8), uFever * 0.5);\r\n      float lum = dot(col, vec3(0.299, 0.587, 0.114));\r\n      col = mix(col, vec3(lum) * vec3(0.8, 0.95, 1.15), uSlow * 0.35);\r\n      col = aces(col);\r\n      col = pow(col, vec3(1.0 / 2.2));\r\n      float vig = smoothstep(0.95, 0.28, length(dc * vec2(1.0, 1.08)));\r\n      col *= mix(0.28, 1.0, vig);\r\n      col = mix(col, vec3(0.95, 0.15, 0.12), uHit * 0.35 * (1.0 - vig));\r\n      col += (hash(uv * uRes + fract(uTime) * 61.0) - 0.5) * 0.04 * (1.0 - uClean);\r\n      col *= 1.0 - uFade;\r\n      gl_FragColor = vec4(col, 1.0);\r\n    }";
